def filter_api_calls(
    logp_with_result: np.ndarray,
    logp_call_only: np.ndarray,
    logp_no_call: np.ndarray,
    tau_filter: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return an ordered keep mask and one finite margin per proposed call."""
    # Validate shapes
    if not (logp_with_result.ndim == 2 and logp_call_only.ndim == 2 and logp_no_call.ndim == 2):
        raise ValueError("All input arrays must be 2D matrices")
    if logp_with_result.shape != logp_call_only.shape or logp_with_result.shape != logp_no_call.shape:
        raise ValueError("Input arrays must have the same shape")
    if logp_with_result.shape[0] == 0 or logp_with_result.shape[1] == 0:
        raise ValueError("Input arrays must not be empty")
    # Validate values: finite and nonpositive
    for arr in [logp_with_result, logp_call_only, logp_no_call]:
        if not np.all(np.isfinite(arr)):
            raise ValueError("All input values must be finite")
        if np.any(arr > 0):
            raise ValueError("All input values must be nonpositive")
    # Validate threshold
    if isinstance(tau_filter, bool):
        raise ValueError("Threshold must not be a boolean")
    try:
        tau_float = float(tau_filter)
    except (TypeError, ValueError):
        raise ValueError("Threshold must be convertible to float")
    if not np.isfinite(tau_float) or tau_float < 0:
        raise ValueError("Threshold must be finite and nonnegative")

    # Compute margins: sum over horizon for with_result and no_call
    sum_with = np.sum(logp_with_result, axis=1)
    sum_no = np.sum(logp_no_call, axis=1)
    margins = sum_with - sum_no  # positive if call reduces loss
    keep_mask = margins > tau_float
    return keep_mask, margins
